const categories=[{"name": "Category 1", "type": "placeholder"}, {"name": "Category 2", "type": "placeholder"}, {"name": "Category 3", "type": "placeholder"}, {"name": "Category 4", "type": "placeholder"}, {"name": "Category 5", "type": "placeholder"}, {"name": "Category 6", "type": "placeholder"}, {"name": "Category 7", "type": "placeholder"}, {"name": "Category 8", "type": "placeholder"}, {"name": "Category 9", "type": "placeholder"}, {"name": "Category 10", "type": "placeholder"}, {"name": "Category 11", "type": "placeholder"}, {"name": "Category 12", "type": "placeholder"}, {"name": "Category 13", "type": "placeholder"}, {"name": "బైబిల్ అతుకుల బొంత", "type": "cat14"}, {"name": "పాషండ మతాలను చీల్చి చెండాడుతున్న స్వప్న సింహాలు 🦁🔥", "type": "cat15"}];
const topics=[{"title": "1. వ్యభిచారిణి స్త్రీ వృత్తాంతం — తరువాత చేర్చబడిన కథనా?", "reference": "యోహాను 7:53–8:11", "content": ["యోహాను 7:53: వారిలో ప్రతివాడును తన తన ఇంటికి వెళ్లెను.", "యోహాను 8:1: యేసు ఒలీవల కొండకు వెళ్లెను.", "యోహాను 8:2: ఉదయమున ఆయన మరల దేవాలయములోనికి రాగా ప్రజలందరు ఆయనయొద్దకు వచ్చిరి; ఆయన కూర్చుండి వారికి బోధించుచుండెను.", "యోహాను 8:3: అప్పుడు శాస్త్రులును పరిసయ్యులును వ్యభిచారమందు పట్టబడిన ఒక స్త్రీని తీసికొని వచ్చి మధ్యలో నిలువబెట్టి,", "యోహాను 8:4: ఆయనతో — బోధకుడా, ఈ స్త్రీ వ్యభిచారము చేయుచుండగా పట్టబడెను.", "యోహాను 8:5: మోషే ధర్మశాస్త్రములో ఇట్టివారిని రాళ్లతో కొట్టవలెనని మనకు ఆజ్ఞాపించెను; నీవేమి చెప్పుచున్నావని అడిగిరి.", "యోహాను 8:6: ఆయనను శోధించి ఆయనమీద నేరము మోపుటకు వీలుకలుగునట్లు వారు ఈ మాట చెప్పిరి. యేసు వంగి తన వ్రేలితో నేలమీద వ్రాయుచుండెను.", "యోహాను 8:7: వారు ఆయనను అడుగుచుండగా ఆయన తల ఎత్తి — మీలో పాపము లేనివాడు మొదట ఆమెపై రాయి వేయవలెనని చెప్పెను.", "యోహాను 8:8: ఆయన మరల వంగి నేలమీద వ్రాయుచుండెను.", "యోహాను 8:9: వారు అది విని పెద్దవారితో మొదలుకొని ఒక్కొక్కరుగా వెళ్లిపోయిరి; యేసు మాత్రమే మిగిలెను, ఆ స్త్రీ మధ్యలో నిలిచి ఉండెను.", "యోహాను 8:10: యేసు తల ఎత్తి ఆమెను చూచి — స్త్రీ, వారు ఎక్కడ? ఎవడును నీకు శిక్ష విధింపలేదా? అని అడిగెను.", "యోహాను 8:11: ఆమె — ఎవడును విధింపలేదు ప్రభువా అని చెప్పగా, యేసు — నేనును నీకు శిక్ష విధింపను; వెళ్లి ఇకమీదట పాపము చేయకుమని చెప్పెను.", "1. ఈ కథ ఎప్పటి వరకు కనిపించలేదు?", "రెండవ మరియు మూడవ శతాబ్దాల ప్రారంభ పాఠ్య సాక్ష్యాలలో ఈ కథ కనిపించదు.\nనాలుగవ శతాబ్దానికి చెందిన కొన్ని ముఖ్యమైన గ్రీకు ప్రతుల్లో కూడా ఈ భాగం లేదు.\nఅంటే ప్రారంభ యోహాను పాఠ్య సంప్రదాయంలో ఈ కథ స్పష్టంగా కనిపించదు.\nఅందువల్ల ఇది అసలు రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ కథ ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "తరువాతి శతాబ్దాలకు చెందిన కొన్ని బైబిల్ ప్రతుల్లో ఈ కథ కనిపించడం ప్రారంభమైంది.\nక్రమంగా ఇది యోహాను 7:53–8:11 మధ్య స్థిరపడింది.\nఅయితే అన్ని ప్రతుల్లో ఒకే సమయంలో ఈ కథ కనిపించలేదు.\nదీనివల్ల ఇది తరువాత పాఠ్యంలో చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ కథను ఎవరు చేర్చారు?", "ఈ కథను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి లేదా చర్చి ఈ కథను చేర్చిందని నిర్ధారించడం సాధ్యం కాదు.\nప్రతులను చేతితో కాపీ చేసే ప్రక్రియలో ఇది పాఠ్యంలోకి వచ్చి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల అసలు ఈ కథను ఎవరు చేర్చారనే విషయం తెలియదు.", "4. బైబిల్‌లో ఈ కథ తరువాత ఎలా చేరింది?", "ప్రారంభ ముఖ్యమైన ప్రతుల్లో లేకపోయిన ఈ కథ తరువాతి పాఠ్య సంప్రదాయాలలో కనిపించింది.\nప్రతులను చేతితో కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో పాఠ్య మార్పులు జరిగే అవకాశం ఉంది.\nక్రమంగా ఈ కథ యోహాను సువార్తలోని ప్రస్తుత స్థానంలో విస్తృతంగా చేరింది.\nఅందువల్ల అసలు పాఠ్యంలో లేని కథ తరువాత ఎలా బైబిల్‌లో స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "2. మార్కు సువార్త చివరి 12 వచనాలు — తరువాత చేర్చబడినవా?", "reference": "మార్కు 16:9–20", "content": ["మార్కు 16:9: వారములో మొదటి దినమున ఉదయమున యేసు లేచి మొదట మరియ మగ్దలేనాకు ప్రత్యక్షమాయెను.", "మార్కు 16:10: ఆమె వెళ్లి ఆయనతో ఉండినవారికి ఆ సంగతి తెలియజేసెను.", "మార్కు 16:11: ఆయన బ్రతికియున్నాడని ఆమెకు ప్రత్యక్షమాయెనని వారు విని నమ్మలేదు.", "మార్కు 16:12: తరువాత వారిలో ఇద్దరు గ్రామమునకు వెళ్లుచుండగా ఆయన వేరొక రూపములో వారికి ప్రత్యక్షమాయెను.", "మార్కు 16:13: వారు వెళ్లి మిగిలినవారికి తెలియజేసిరి; వారిని కూడ వారు నమ్మలేదు.", "మార్కు 16:14: తరువాత పదకొండుమంది భోజనము చేయుచుండగా ఆయన వారికి ప్రత్యక్షమై వారి అవిశ్వాసమును గూర్చి మందలించెను.", "మార్కు 16:15: మీరు సర్వలోకమునకు వెళ్లి సర్వసృష్టికి సువార్తను ప్రకటించుడి అని వారితో చెప్పెను.", "మార్కు 16:16: విశ్వసించి బాప్తిస్మము పొందినవాడు రక్షింపబడును; నమ్మనివాడు శిక్షకు పాత్రుడగును.", "మార్కు 16:17: విశ్వసించినవారి వెంట ఈ సూచక క్రియలు జరుగును; నా నామమున దయ్యములను వెళ్లగొట్టుదురు, కొత్త భాషలు మాటలాడుదురు.", "మార్కు 16:18: పాములను పట్టుకొందురు; ప్రాణహానికరమైనది ఏదైనను త్రాగినను వారికి హాని కలుగదు; రోగుల మీద చేతులుంచగా వారు స్వస్థత పొందుదురు.", "మార్కు 16:19: ప్రభువైన యేసు వారితో మాటలాడిన తరువాత పరలోకమునకు తీసుకోబడెను.", "మార్కు 16:20: వారు బయలుదేరి అన్ని చోట్ల ప్రకటించిరి; ప్రభువు వారితో కలిసి పనిచేసి సూచక క్రియల ద్వారా వాక్యమును స్థిరపరచెను.", "1. మార్కు సువార్త చివరి భాగం ఎప్పటి వరకు కనిపించలేదు?", "మార్కు 16:9–20 భాగం కొన్ని అత్యంత పురాతన గ్రీకు ప్రతుల్లో కనిపించదు.\nనాలుగవ శతాబ్దానికి చెందిన ముఖ్యమైన కోడెక్స్ సైనైటికస్ మరియు కోడెక్స్ వాటికానస్ మార్కు 16:8 వద్ద ముగుస్తాయి.\nఅంటే ప్రారంభ ముఖ్యమైన పాఠ్య సాక్ష్యాలలో ఈ చివరి 12 వచనాలు లేవు.\nఅందువల్ల అసలు మార్కు సువార్త ఎక్కడ ముగిసిందనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ చివరి 12 వచనాలు ఎప్పుడు కనిపించడం ప్రారంభమయ్యాయి?", "తరువాతి శతాబ్దాలకు చెందిన అనేక గ్రీకు బైబిల్ ప్రతుల్లో మార్కు 16:9–20 కనిపిస్తుంది.\nక్రమంగా ఈ భాగం మార్కు సువార్త యొక్క సాధారణ ముగింపుగా విస్తృతంగా ఉపయోగించబడింది.\nఅయితే ప్రారంభ ప్రతులు మరియు తరువాతి ప్రతుల మధ్య స్పష్టమైన పాఠ్య వ్యత్యాసం ఉంది.\nదీనివల్ల ఈ ముగింపు తరువాత చేర్చబడిందా అనే ప్రశ్న వస్తుంది.", "3. మార్కు 16:9–20ను ఎవరు చేర్చారు?", "ఈ చివరి 12 వచనాలను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి ఈ భాగాన్ని రచించాడని ఖచ్చితంగా నిర్ధారించబడలేదు.\nప్రతులను చేతితో కాపీ చేసే పాఠ్య సంప్రదాయంలో ఇది చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ దీర్ఘ ముగింపును ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. మార్కు 16:8 తర్వాత అసలు కథ ముగిసిందా?", "కొన్ని ముఖ్యమైన పురాతన గ్రీకు ప్రతుల్లో మార్కు సువార్త 16:8 వద్దనే ముగుస్తుంది.\nఅక్కడ స్త్రీలు భయంతో సమాధి నుండి వెళ్లిపోయినట్లు కథనం ముగుస్తుంది.\n16:9–20లో ఉన్న యేసు ప్రత్యక్షతలు మరియు ఇతర వివరాలు ఆ ప్రతుల్లో కనిపించవు.\nఅందువల్ల మార్కు అసలు రచన నిజంగా 16:8 వద్దనే ముగిసిందా అనే ప్రశ్న ఏర్పడుతుంది.", "5. ఈ భాగం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "ప్రారంభ ముఖ్యమైన ప్రతుల్లో లేకపోయిన దీర్ఘ ముగింపు తరువాతి పాఠ్య సంప్రదాయాలలో కనిపించింది.\nప్రతులను చేతితో కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఈ భాగం విస్తృతంగా వ్యాపించింది.\nక్రమంగా మార్కు 16:9–20 అనేక బైబిల్ సంచికల్లో సాధారణ ముగింపుగా చేరింది.\nఅందువల్ల అసలు పాఠ్యంలో లేని భాగం తరువాత ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "3. 1 యోహాను 5:7–8 — తరువాత చేర్చబడిన త్రిత్వ వచనమా?", "reference": "1 యోహాను 5:7–8", "content": ["1 యోహాను 5:7: పరలోకమందు సాక్ష్యమిచ్చువారు ముగ్గురున్నారు; తండ్రి, వాక్యము, పరిశుద్ధాత్మ; ఈ ముగ్గురు ఒక్కరై యున్నారు.", "1 యోహాను 5:8: భూమిమీద సాక్ష్యమిచ్చువారు ముగ్గురున్నారు; ఆత్మ, నీరు, రక్తము; ఈ ముగ్గురు ఏకీభవించి యున్నారు.", "1. ఈ అదనపు త్రిత్వ వచనం ఎప్పటి వరకు కనిపించలేదు?", "ప్రారంభ కాలానికి చెందిన ముఖ్యమైన గ్రీకు మాన్యుస్క్రిప్టుల్లో పరలోక సాక్ష్యానికి సంబంధించిన ఈ విస్తృత పదాలు కనిపించవు.\nప్రాచీన గ్రీకు పాఠ్యాలలో ఆత్మ, నీరు మరియు రక్తము సాక్ష్యమిచ్చేవారిగా మాత్రమే కనిపిస్తాయి.\nతండ్రి, వాక్యము మరియు పరిశుద్ధాత్మకు సంబంధించిన విస్తృత వాక్యం తరువాతి పాఠ్య సంప్రదాయాలలో కనిపించింది.\nఅందువల్ల ఈ అదనపు భాగం అసలు రచనలో ఉందా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "ఈ విస్తృత రూపం మొదట లాటిన్ పాఠ్య సంప్రదాయంలో కనిపించడం ప్రారంభమైంది.\nతరువాతి కాలంలో కొన్ని గ్రీకు ప్రతుల్లో కూడా ఈ పదాలు కనిపించాయి.\nక్రమంగా కొన్ని బైబిల్ అనువాదాలలో ఈ పూర్తి వాక్యం ప్రధాన పాఠ్యంలో చేరింది.\nదీనివల్ల ఈ పదాలు తరువాత పాఠ్యంలోకి ప్రవేశించాయా అనే ప్రశ్న వస్తుంది.", "3. ఈ అదనపు పదాలను ఎవరు చేర్చారు?", "ఈ పదాలను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి ఈ వచనాన్ని మార్చాడని ఖచ్చితంగా నిర్ధారించబడలేదు.\nపాఠ్య ప్రతులను కాపీ చేయడం మరియు అనువదించడం జరిగిన ప్రక్రియలో ఈ విస్తృత రూపం అభివృద్ధి చెందింది.\nఅందువల్ల ఈ భాగాన్ని మొదట ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ వచనం బైబిల్‌లో తరువాత ఎలా స్థిరపడింది?", "లాటిన్ పాఠ్య సంప్రదాయంలో కనిపించిన విస్తృత రూపం తరువాత కొన్ని బైబిల్ సంచికల్లో చేరింది.\nతరువాతి కాలపు పాఠ్య సంప్రదాయాలు మరియు అనువాదాల ద్వారా ఇది మరింత విస్తరించింది.\nక్రమంగా “తండ్రి, వాక్యము, పరిశుద్ధాత్మ” అనే రూపం కొన్ని బైబిళ్లలో స్థిరపడింది.\nఅందువల్ల ప్రారంభ గ్రీకు ప్రతుల్లో లేని పదాలు తరువాత ఎలా ప్రధాన పాఠ్యంలో చేరాయనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "4. యోహాను 5:3b–4 — దేవదూత నీటిని కదిలించే వచనం తరువాత చేర్చబడిందా?", "reference": "యోహాను 5:3b–4", "content": ["యోహాను 5:3: అక్కడ గ్రుడ్డివారు, కుంటివారు, ఎండిపోయిన అవయవములు గలవారు అనేకమంది పడి నీరు కదలుట కొరకు కనిపెట్టుచుండిరి.", "యోహాను 5:4: ఒక సమయమందు ప్రభువు దూత కొలనులో దిగివచ్చి నీటిని కదిలించుచుండెను; నీరు కదలిన తరువాత మొదట దిగినవాడు ఏ రోగముగలవాడైనను స్వస్థపడుచుండెను.", "1. దేవదూత నీటిని కదిలించే వచనం ఎప్పటి వరకు కనిపించలేదు?", "యోహాను 5:3b–4లోని నీరు కదలుట మరియు దేవదూత దిగివచ్చుటకు సంబంధించిన పదాలు కొన్ని పురాతన గ్రీకు ప్రతుల్లో కనిపించవు.\nప్రారంభ ముఖ్యమైన పాఠ్య సాక్ష్యాలలో ఈ వివరణ లేకుండా కథనం కొనసాగుతుంది.\nతరువాతి కాలపు అనేక ప్రతుల్లో ఈ అదనపు వివరణ కనిపిస్తుంది.\nఅందువల్ల ఈ వచనం అసలు యోహాను రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "తరువాతి శతాబ్దాలకు చెందిన కొన్ని గ్రీకు మరియు ఇతర భాషల ప్రతుల్లో ఈ వచనం కనిపించింది.\nక్రమంగా బెతెస్థ కొలనులో నీరు ఎందుకు కదులుతుందనే వివరణగా ఈ భాగం పాఠ్యంలో చేరింది.\nఅయితే ప్రారంభ ప్రతుల్లో ఈ పూర్తి వివరణ కనిపించదు.\nదీనివల్ల ఈ వచనం తరువాత కాలంలో చేర్చబడిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ అదనపు వివరణను ఎవరు చేర్చారు?", "ఈ వచనాన్ని మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక లేఖకుడు లేదా ఒక నిర్దిష్ట చర్చి దీనిని చేర్చిందని ఖచ్చితంగా చెప్పడం సాధ్యం కాదు.\nకథలోని నీరు కదలడానికి కారణం వివరించేందుకు ఇది పాఠ్యంలోకి వచ్చి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ భాగాన్ని మొదట ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "ప్రారంభ ప్రతుల్లో లేని ఈ వివరణ తరువాతి పాఠ్య సంప్రదాయాలలో కనిపించింది.\nప్రతులను చేతితో కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఈ భాగం అనేక ప్రతుల్లో చేరింది.\nక్రమంగా యోహాను 5:4 అనేక బైబిల్ సంచికల్లో ప్రధాన వచనంగా స్థిరపడింది.\nఅందువల్ల అసలు పాఠ్యంలో లేని వివరణ తరువాత ఎలా బైబిల్‌లో చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "5. అపొస్తల కార్యములు 8:37 — తరువాత చేర్చబడిన వచనమా?", "reference": "అపొస్తల కార్యములు 8:36–38", "content": ["అపొస్తల కార్యములు 8:36: వారు మార్గమున వెళ్లుచుండగా ఒక నీటి స్థలమునకు వచ్చిరి; నపుంసకుడు — ఇదిగో నీరు, నేను బాప్తిస్మము పొందుటకు ఆటంకమేమి? అని చెప్పెను.", "అపొస్తల కార్యములు 8:37: ఫిలిప్పు — నీవు పూర్ణహృదయముతో విశ్వసించినయెడల పొందవచ్చునని చెప్పెను. అతడు — యేసుక్రీస్తు దేవుని కుమారుడని నేను విశ్వసించుచున్నానని ప్రత్యుత్తరమిచ్చెను.", "అపొస్తల కార్యములు 8:38: అతడు రథము నిలుపవలెనని ఆజ్ఞాపించెను; ఫిలిప్పును నపుంసకుడును ఇద్దరు నీటిలో దిగిరి, అతడు అతనికి బాప్తిస్మమిచ్చెను.", "1. అపొస్తల కార్యములు 8:37 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని అత్యంత పురాతన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nఆ ప్రతుల్లో అపొస్తల కార్యములు 8:36 తరువాత కథనం నేరుగా 8:38కు కొనసాగుతుంది.\nఅంటే ఫిలిప్పు మరియు నపుంసకుని మధ్య ఉన్న విశ్వాస ప్రకటన ఆ ప్రారంభ ప్రతుల్లో లేదు.\nఅందువల్ల 8:37 అసలు రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "తరువాతి కాలపు కొన్ని గ్రీకు మరియు లాటిన్ ప్రతుల్లో ఈ పూర్తి వచనం కనిపించింది.\nక్రమంగా బాప్తిస్మానికి ముందు విశ్వాస ప్రకటనగా ఈ వచనం విస్తృతంగా ఉపయోగించబడింది.\nఅయితే ప్రారంభ ముఖ్యమైన ప్రతుల్లో ఇది లేకపోవడం పాఠ్య వ్యత్యాసాన్ని చూపుతుంది.\nదీనివల్ల ఈ వచనం తరువాత చేర్చబడిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "అపొస్తల కార్యములు 8:37ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి ఈ వచనాన్ని చేర్చాడని ఖచ్చితంగా నిర్ధారించబడలేదు.\nప్రారంభ క్రైస్తవ విశ్వాస ప్రకటన లేదా బాప్తిస్మ సంప్రదాయం ప్రభావంతో ఇది చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి ప్రతులలో కనిపించిన ఈ విశ్వాస ప్రకటన క్రమంగా అనేక బైబిల్ సంచికల్లో చేరింది.\nప్రతులను చేతితో కాపీ చేయడం మరియు పాఠ్య సంప్రదాయాల ద్వారా ఇది విస్తరించింది.\nకొన్ని పాత అనువాదాలలో ఇది ప్రధాన వచనంగా కొనసాగింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "6. లూకా 22:43–44 — రక్తబిందువుల వంటి చెమట వచనాలు అసలువా?", "reference": "లూకా 22:43–44", "content": ["లూకా 22:43: అప్పుడు పరలోకమునుండి ఒక దూత ఆయనకు ప్రత్యక్షమై ఆయనను బలపరచెను.", "లూకా 22:44: ఆయన అత్యంత వేదనతో మరింతగా ప్రార్థించెను; ఆయన చెమట భూమిమీద పడుచున్న రక్తబిందువులవలె ఉండెను.", "1. ఈ రెండు వచనాలు ఎప్పటి వరకు కనిపించలేదు?", "లూకా 22:43–44 కొన్ని పురాతన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించవు.\nప్రారంభ పాఠ్య సంప్రదాయాలలో ఈ వచనాలు లేకుండా యేసు ప్రార్థన కథనం కొనసాగుతుంది.\nమరికొన్ని పురాతన ప్రతుల్లో మాత్రం ఈ రెండు వచనాలు కనిపిస్తాయి.\nఅందువల్ల ఈ వచనాలు అసలు లూకా రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనాలు ఎప్పుడు కనిపించడం ప్రారంభమయ్యాయి?", "తరువాతి కాలపు అనేక ప్రతుల్లో దూత ప్రత్యక్షమవడం మరియు రక్తబిందువుల వంటి చెమట వివరాలు కనిపించాయి.\nక్రమంగా ఈ రెండు వచనాలు లూకా సువార్తలో విస్తృతంగా ఉపయోగించబడ్డాయి.\nకానీ పురాతన ప్రతుల మధ్య ఈ విషయంపై స్పష్టమైన వ్యత్యాసం ఉంది.\nదీనివల్ల ఈ వచనాలు తరువాత పాఠ్యంలో చేరాయా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాలను ఎవరు చేర్చారు?", "ఈ రెండు వచనాలను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట లేఖకుడు లేదా వ్యక్తి దీనిని చేర్చాడని ఖచ్చితంగా చెప్పడం సాధ్యం కాదు.\nయేసు వేదనను మరింత స్పష్టంగా చూపించేందుకు ఈ వివరాలు చేరి ఉండవచ్చని పరిశీలించబడుతుంది.\nఅందువల్ల ఈ భాగాన్ని మొదట ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ వచనాలు బైబిల్‌లో తరువాత ఎలా స్థిరపడ్డాయి?", "కొన్ని పాఠ్య సంప్రదాయాలలో ఉన్న ఈ రెండు వచనాలు తరువాత అనేక ప్రతుల్లో విస్తరించాయి.\nప్రతులను చేతితో కాపీ చేసే ప్రక్రియ ద్వారా ఇవి విస్తృతంగా వ్యాపించాయి.\nక్రమంగా లూకా 22:43–44 అనేక బైబిల్ సంచికల్లో ప్రధాన పాఠ్యంగా స్థిరపడ్డాయి.\nఅందువల్ల ఈ వచనాలు అసలు రచనలో ఉన్నాయా లేదా తరువాత చేరాయా అనే ప్రశ్న కొనసాగుతోంది."]}, {"title": "7. లూకా 23:34 — “తండ్రీ, వీరిని క్షమించుము” వచనం అసలుదా?", "reference": "లూకా 23:34", "content": ["లూకా 23:34: యేసు — తండ్రీ, వీరేమి చేయుచున్నారో వీరెరుగరు గనుక వీరిని క్షమించుమని చెప్పెను. వారు ఆయన వస్త్రములను పంచుకొని చీట్లు వేసిరి.", "1. ఈ వచనం ఎప్పటి వరకు అన్ని ప్రతుల్లో కనిపించలేదు?", "లూకా 23:34లోని “తండ్రీ, వీరిని క్షమించుము” అనే మాట కొన్ని పురాతన గ్రీకు ప్రతుల్లో కనిపించదు.\nమరికొన్ని ప్రాచీన పాఠ్య సాక్ష్యాలలో ఈ వచనం పూర్తిగా ఉంటుంది.\nఅంటే ప్రారంభ మాన్యుస్క్రిప్ట్ సంప్రదాయంలో ఈ మాటపై వ్యత్యాసం ఉంది.\nఅందువల్ల ఈ వాక్యం అసలు లూకా రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వాక్యం ఎప్పుడు విస్తృతంగా కనిపించడం ప్రారంభమైంది?", "తరువాతి కాలపు అనేక బైబిల్ ప్రతుల్లో ఈ వాక్యం స్పష్టంగా కనిపిస్తుంది.\nక్రమంగా ఇది యేసు సిలువపై పలికిన ప్రసిద్ధ మాటలలో ఒకటిగా స్థిరపడింది.\nఅయితే కొన్ని పురాతన ప్రతుల్లో ఇది లేకపోవడం ప్రత్యేక పాఠ్య సమస్యగా ఉంది.\nదీనివల్ల ఈ మాట తరువాత పాఠ్యంలో చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "ఈ వాక్యాన్ని మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి లేదా లేఖకుడిని దీనికి సంబంధించి ఖచ్చితంగా గుర్తించడం సాధ్యం కాదు.\nప్రతులను కాపీ చేసే పాఠ్య సంప్రదాయంలో ఈ మాట చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "కొన్ని పురాతన ప్రతుల్లో ఉన్న ఈ మాట తరువాతి పాఠ్య సంప్రదాయాలలో విస్తృతంగా వ్యాపించింది.\nప్రతులను కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఇది అనేక బైబిల్ ప్రతుల్లో చేరింది.\nక్రమంగా ఈ వచనం లూకా 23:34లో ప్రధాన పాఠ్యంగా స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల మధ్య ఉన్న వ్యత్యాసం ఇప్పటికీ పాఠ్య పరిశోధనలో ప్రశ్నగా ఉంది."]}, {"title": "8. మత్తయి 17:21 — తరువాత చేర్చబడిన వచనమా?", "reference": "మత్తయి 17:20–21", "content": ["మత్తయి 17:20: యేసు వారితో — మీ అల్పవిశ్వాసము వలననే; ఆవగింజంత విశ్వాసము మీకు ఉన్నయెడల ఈ కొండతో ఇక్కడనుండి అక్కడికి పొమ్మని చెప్పినను అది పోవును; మీకు అసాధ్యమైనదేదియు ఉండదని చెప్పెను.", "మత్తయి 17:21: అయితే ప్రార్థనవలనను ఉపవాసమువలనను తప్ప ఈ జాతి బయటికి పోదని చెప్పెను.", "1. మత్తయి 17:21 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని అత్యంత పురాతన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nఆ ప్రతుల్లో మత్తయి 17:20 తరువాత కథనం నేరుగా తరువాతి వచనానికి కొనసాగుతుంది.\nఅయితే తరువాతి అనేక ప్రతుల్లో “ప్రార్థన మరియు ఉపవాసం” అనే వచనం కనిపిస్తుంది.\nఅందువల్ల ఈ వచనం అసలు మత్తయి రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "తరువాతి కాలపు గ్రీకు ప్రతుల్లో ఈ వచనం కనిపించడం ప్రారంభమైంది.\nమార్కు 9:29లో ఉన్న సమానమైన బోధనతో సంబంధం ఉండటం కూడా గమనించదగిన విషయం.\nక్రమంగా ఈ వచనం కొన్ని బైబిల్ పాఠ్య సంప్రదాయాలలో స్థిరపడింది.\nదీనివల్ల ఇది తరువాత పాఠ్యంలో చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "ఈ వచనాన్ని మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి దీనిని మత్తయి సువార్తలో చేర్చాడని నిర్ధారించడం సాధ్యం కాదు.\nఇతర సువార్తలలోని సమాంతర కథనం ప్రభావంతో ఇది చేరి ఉండవచ్చని పరిశీలించబడుతుంది.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం బైబిల్‌లో తరువాత ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో కనిపించిన ఈ వచనం అనేక ప్రతుల ద్వారా విస్తరించింది.\nప్రతులను చేతితో కాపీ చేసే సమయంలో ఇది ప్రధాన పాఠ్యంలో చేరింది.\nక్రమంగా కొన్ని బైబిల్ అనువాదాలలో మత్తయి 17:21గా స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "9. మత్తయి 18:11 — తరువాతి ప్రతుల్లో కనిపించే వచనమా?", "reference": "మత్తయి 18:10–12", "content": ["మత్తయి 18:10: ఈ చిన్నవారిలో ఒకనినైనను తృణీకరింపకుండ చూచుకొనుడి; వీరి దూతలు పరలోకమందు ఎల్లప్పుడు పరలోకమందున్న నా తండ్రి ముఖము చూచుచున్నారని మీతో చెప్పుచున్నాను.", "మత్తయి 18:11: మనుష్యకుమారుడు నశించినదానిని రక్షించుటకు వచ్చెను.", "మత్తయి 18:12: మీకేమి తోచుచున్నది? ఒక మనుష్యునికి నూరు గొఱ్ఱెలుండగా వాటిలో ఒకటి తప్పిపోయినయెడల తొంభై తొమ్మిదింటిని కొండలమీద విడిచిపెట్టి తప్పిపోయినదానిని వెదకుటకు వెళ్లడా?", "1. మత్తయి 18:11 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు ప్రతుల్లో కనిపించదు.\nఆ ప్రతుల్లో మత్తయి 18:10 తరువాత కథనం నేరుగా 18:12కు కొనసాగుతుంది.\n“మనుష్యకుమారుడు నశించినదానిని రక్షించుటకు వచ్చెను” అనే వాక్యం తరువాతి ప్రతుల్లో కనిపిస్తుంది.\nఅందువల్ల ఈ వచనం అసలు మత్తయి రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "తరువాతి కాలపు కొన్ని పాఠ్య సంప్రదాయాలలో ఈ వచనం కనిపించడం ప్రారంభమైంది.\nలూకా 19:10లో ఉన్న సమానమైన మాటతో దీనికి సంబంధం ఉందని గమనించబడుతుంది.\nక్రమంగా కొన్ని గ్రీకు ప్రతులు మరియు బైబిల్ అనువాదాలలో ఇది చేరింది.\nదీనివల్ల ఇతర సువార్తల ప్రభావంతో ఈ వచనం చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "మత్తయి 18:11ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి లేదా లేఖకుడిని ఖచ్చితంగా గుర్తించడం సాధ్యం కాదు.\nసమాంతర సువార్తలోని వాక్యం ప్రభావంతో ప్రతుల కాపీ ప్రక్రియలో చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో ఉన్న ఈ వచనం క్రమంగా అనేక ప్రతుల్లో విస్తరించింది.\nప్రతులను చేతితో కాపీ చేసే సమయంలో ఇది మత్తయి 18వ అధ్యాయంలో చేరింది.\nతరువాత కొన్ని బైబిల్ సంచికల్లో ఇది ప్రత్యేక వచన సంఖ్యతో స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "10. మత్తయి 23:14 — తరువాత చేర్చబడిన వచనమా?", "reference": "మత్తయి 23:13–15", "content": ["మత్తయి 23:13: అయ్యో, శాస్త్రులారా, పరిసయ్యులారా, వేషధారులారా! మీరు మనుష్యుల యెదుట పరలోకరాజ్యము మూసివేయుచున్నారు; మీరును లోపలికి వెళ్లరు, వెళ్లుచున్నవారిని వెళ్లనియ్యరు.", "మత్తయి 23:14: అయ్యో, శాస్త్రులారా, పరిసయ్యులారా, వేషధారులారా! మీరు విధవరాండ్ర ఇండ్లను మింగివేసి కపటముగా దీర్ఘప్రార్థనలు చేయుచున్నారు; అందుచేత మీకు మరింత శిక్ష కలుగును.", "మత్తయి 23:15: అయ్యో, శాస్త్రులారా, పరిసయ్యులారా, వేషధారులారా! ఒకనిని మతస్థునిగా చేయుటకు సముద్రమును భూమిని చుట్టివచ్చి, అతడు అయిన తరువాత మీకంటె రెండంతలు నరకపాత్రునిగా చేయుచున్నారు.", "1. మత్తయి 23:14 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nఆ ప్రతుల్లో మత్తయి 23:13 తరువాత కథనం నేరుగా 23:15కు కొనసాగుతుంది.\nవిధవరాండ్ర ఇండ్లను మింగివేయడం మరియు దీర్ఘ ప్రార్థనలకు సంబంధించిన వాక్యం తరువాతి ప్రతుల్లో కనిపిస్తుంది.\nఅందువల్ల ఈ వచనం అసలు మత్తయి రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "తరువాతి కాలపు కొన్ని పాఠ్య సంప్రదాయాలలో ఈ వచనం కనిపించింది.\nమార్కు 12:40 మరియు లూకా 20:47లో ఉన్న సమానమైన వాక్యాలతో దీనికి సంబంధం ఉంది.\nక్రమంగా ఈ మాట మత్తయి సువార్తలోని కొన్ని ప్రతుల్లో చేరింది.\nదీనివల్ల సమాంతర సువార్తల ప్రభావంతో ఇది చేర్చబడిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "ఈ వచనాన్ని మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట లేఖకుడు దీనిని మత్తయి సువార్తలో చేర్చాడని నిర్ధారించడం సాధ్యం కాదు.\nఇతర సువార్తలలోని సమానమైన మాటలు ప్రతుల కాపీ సమయంలో చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో ఉన్న ఈ వచనం క్రమంగా అనేక బైబిల్ ప్రతుల్లో చేరింది.\nప్రతులను చేతితో కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఇది విస్తరించింది.\nకొన్ని సంప్రదాయ బైబిల్ అనువాదాలలో మత్తయి 23:14గా స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా ప్రధాన పాఠ్యంలో చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "11. మార్కు 7:16 — తరువాతి ప్రతుల్లో కనిపించే వచనమా?", "reference": "మార్కు 7:15–17", "content": ["మార్కు 7:15: వెలుపల నుండి మనుష్యునిలో ప్రవేశించునది అతనిని అపవిత్రపరచలేదు; మనుష్యునిలోనుండి బయటికి వచ్చునవే అతనిని అపవిత్రపరచును.", "మార్కు 7:16: వినుటకు చెవులుగలవాడు వినునుగాక.", "మార్కు 7:17: ఆయన జనసమూహమును విడిచి ఇంటిలోనికి వెళ్లిన తరువాత ఆయన శిష్యులు ఈ ఉపమానము విషయమై ఆయనను అడిగిరి.", "1. మార్కు 7:16 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు ప్రతుల్లో కనిపించదు.\nఆ ప్రతుల్లో మార్కు 7:15 తరువాత కథనం నేరుగా 7:17కు కొనసాగుతుంది.\n“వినుటకు చెవులుగలవాడు వినునుగాక” అనే మాట తరువాతి ప్రతుల్లో కనిపిస్తుంది.\nఅందువల్ల ఈ వచనం అసలు మార్కు రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "తరువాతి కాలపు అనేక గ్రీకు ప్రతుల్లో ఈ వచనం కనిపించడం ప్రారంభమైంది.\nఇలాంటి మాటలు ఇతర సందర్భాలలో కూడా యేసు బోధనల్లో కనిపిస్తాయి.\nక్రమంగా ఈ వాక్యం మార్కు 7వ అధ్యాయంలోని కొన్ని పాఠ్య సంప్రదాయాలలో చేరింది.\nదీనివల్ల ఇది తరువాతి పాఠ్య విస్తరణా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "మార్కు 7:16ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి ఈ వచనాన్ని చేర్చాడని ఖచ్చితంగా చెప్పడం సాధ్యం కాదు.\nయేసు ఇతర బోధనల్లో ఉన్న సాధారణ వాక్య రూపం కారణంగా ఇది చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి ప్రతుల్లో కనిపించిన ఈ వాక్యం క్రమంగా పాఠ్య సంప్రదాయంలో విస్తరించింది.\nప్రతులను చేతితో కాపీ చేసే సమయంలో ఇది మార్కు 7:15 మరియు 7:17 మధ్య చేరింది.\nతరువాత కొన్ని బైబిల్ సంచికల్లో మార్కు 7:16గా ప్రత్యేక వచన సంఖ్య పొందింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "12. మార్కు 9:44 — తరువాత చేర్చబడిన వచనమా?", "reference": "మార్కు 9:43–48", "content": ["మార్కు 9:43: నీ చెయ్యి నిన్ను అభ్యంతరపరచినయెడల దానిని నరికివేయుము; రెండు చేతులుగలవాడవై ఆరని అగ్నిగల నరకములో పడుటకంటె కుంటివాడవై జీవములో ప్రవేశించుట నీకు మేలు.", "మార్కు 9:44: అక్కడ వారి పురుగు చావదు, అగ్ని ఆరదు.", "మార్కు 9:45: నీ కాలు నిన్ను అభ్యంతరపరచినయెడల దానిని నరికివేయుము; రెండు కాళ్లుగలవాడవై నరకములో పడుటకంటె కుంటివాడవై జీవములో ప్రవేశించుట నీకు మేలు.", "మార్కు 9:46: అక్కడ వారి పురుగు చావదు, అగ్ని ఆరదు.", "మార్కు 9:47: నీ కన్ను నిన్ను అభ్యంతరపరచినయెడల దానిని పెరికివేయుము; రెండు కన్నులుగలవాడవై అగ్నిగల నరకములో పడుటకంటె ఒక కన్నుగలవాడవై దేవుని రాజ్యములో ప్రవేశించుట నీకు మేలు.", "మార్కు 9:48: అక్కడ వారి పురుగు చావదు, అగ్ని ఆరదు.", "1. మార్కు 9:44 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nఆ ప్రతుల్లో మార్కు 9:43 తరువాత కథనం నేరుగా 9:45కు కొనసాగుతుంది.\n“అక్కడ వారి పురుగు చావదు, అగ్ని ఆరదు” అనే వాక్యం మొదటిసారి అక్కడ ఉండదు.\nఅందువల్ల 9:44 అసలు మార్కు రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "మార్కు 9:48లో ఇదే వాక్యం స్పష్టంగా కనిపిస్తుంది.\nకొన్ని తరువాతి ప్రతులలో ఈ వాక్యాన్ని 9:43 తరువాత కూడా పునరావృతం చేశారు.\nఅదే మాటను కథనం మధ్యలో మళ్లీ చేర్చడం పాఠ్య విస్తరణకు కారణమై ఉండవచ్చు.\nదీనివల్ల 9:48 ప్రభావంతో 9:44 ఏర్పడిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "మార్కు 9:44ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట లేఖకుడు దీనిని చేర్చాడని ఖచ్చితంగా చెప్పడం సాధ్యం కాదు.\nప్రతులను కాపీ చేసే సమయంలో 9:48లోని వాక్యం ఇక్కడికి పునరావృతమై ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో ఈ పునరావృత వాక్యం కనిపించడం ప్రారంభమైంది.\nప్రతులను చేతితో కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఇది విస్తరించింది.\nక్రమంగా కొన్ని బైబిల్ సంచికల్లో మార్కు 9:44గా ప్రత్యేక వచనంగా చేరింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "13. మార్కు 9:46 — తరువాత చేర్చబడిన వచనమా?", "reference": "మార్కు 9:45–48", "content": ["మార్కు 9:45: నీ కాలు నిన్ను అభ్యంతరపరచినయెడల దానిని నరికివేయుము; రెండు కాళ్లుగలవాడవై నరకములో పడుటకంటె కుంటివాడవై జీవములో ప్రవేశించుట నీకు మేలు.", "మార్కు 9:46: అక్కడ వారి పురుగు చావదు, అగ్ని ఆరదు.", "మార్కు 9:47: నీ కన్ను నిన్ను అభ్యంతరపరచినయెడల దానిని పెరికివేయుము; రెండు కన్నులుగలవాడవై అగ్నిగల నరకములో పడుటకంటె ఒక కన్నుగలవాడవై దేవుని రాజ్యములో ప్రవేశించుట నీకు మేలు.", "మార్కు 9:48: అక్కడ వారి పురుగు చావదు, అగ్ని ఆరదు.", "1. మార్కు 9:46 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nఆ ప్రతుల్లో మార్కు 9:45 తరువాత కథనం నేరుగా 9:47కు కొనసాగుతుంది.\nఅక్కడ “వారి పురుగు చావదు, అగ్ని ఆరదు” అనే వాక్యం మధ్యలో ఉండదు.\nఅందువల్ల 9:46 అసలు మార్కు రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "మార్కు 9:48లో ఇదే వాక్యం అసలు కథనంలో కనిపిస్తుంది.\nకొన్ని తరువాతి ప్రతులలో ఈ వాక్యాన్ని 9:45 తరువాత కూడా పునరావృతం చేశారు.\nమార్కు 9:44 మాదిరిగానే ఇది కూడా పునరావృత పాఠ్యంగా ఏర్పడి ఉండవచ్చు.\nదీనివల్ల 9:48లోని వాక్యం ఇక్కడికి చేర్చబడిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "మార్కు 9:46ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి దీనిని చేర్చాడని ఖచ్చితంగా నిర్ధారించబడలేదు.\nప్రతులను చేతితో కాపీ చేసే సమయంలో పునరావృత వాక్యం చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో ఈ వచనం కనిపించడం ప్రారంభమైంది.\nకాపీ చేయబడిన ప్రతుల ద్వారా ఇది మరింత విస్తరించింది.\nక్రమంగా కొన్ని బైబిల్ సంచికల్లో మార్కు 9:46గా ప్రత్యేక వచనంగా స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "14. మార్కు 11:26 — తరువాత చేర్చబడిన వచనమా?", "reference": "మార్కు 11:25–26", "content": ["మార్కు 11:25: మీరు నిలువబడి ప్రార్థన చేయునప్పుడు ఎవనిమీదనైన మీకు విరోధముండినయెడల అతనిని క్షమించుడి; అప్పుడు పరలోకమందున్న మీ తండ్రియు మీ అపరాధములను క్షమించును.", "మార్కు 11:26: మీరు క్షమింపనియెడల పరలోకమందున్న మీ తండ్రియు మీ అపరాధములను క్షమింపడు.", "1. మార్కు 11:26 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు ప్రతుల్లో కనిపించదు.\nఆ ప్రతుల్లో మార్కు 11:25 తరువాత కథనం నేరుగా తరువాతి వచనానికి కొనసాగుతుంది.\nక్షమించకపోతే దేవుడు క్షమించడనే వాక్యం అక్కడ ఉండదు.\nఅందువల్ల 11:26 అసలు మార్కు రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "మత్తయి 6:15లో ఇదే భావానికి సమానమైన బోధన కనిపిస్తుంది.\nకొన్ని తరువాతి పాఠ్య సంప్రదాయాలలో ఆ సమానమైన వాక్యం మార్కు సువార్తలో కూడా చేరింది.\nకథనాన్ని మరింత స్పష్టంగా చేయడానికి ఇది చేర్చబడి ఉండవచ్చని భావిస్తారు.\nదీనివల్ల సమాంతర బోధన ప్రభావంతో ఈ వచనం చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "మార్కు 11:26ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట లేఖకుడు దీనిని చేర్చాడని ఖచ్చితంగా చెప్పడం సాధ్యం కాదు.\nఇతర సువార్తలలోని సమానమైన బోధన ప్రభావంతో ఇది చేరి ఉండవచ్చని పరిశీలించబడుతుంది.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి ప్రతులలో కనిపించిన ఈ వాక్యం క్రమంగా పాఠ్య సంప్రదాయంలో విస్తరించింది.\nప్రతులను చేతితో కాపీ చేసే సమయంలో ఇది మార్కు 11వ అధ్యాయంలో చేరింది.\nతరువాత కొన్ని బైబిల్ అనువాదాలలో మార్కు 11:26గా స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా ప్రధాన పాఠ్యంలో చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "15. మార్కు 15:28 — తరువాత చేర్చబడిన వచనమా?", "reference": "మార్కు 15:27–28", "content": ["మార్కు 15:27: ఆయనతో కూడ ఇద్దరు దొంగలను ఒకనిని ఆయన కుడివైపునను ఒకనిని ఎడమవైపునను సిలువవేసిరి.", "మార్కు 15:28: అప్పుడు — ఆయన అతిక్రమించువారితో ఎంచబడెను అని చెప్పిన లేఖనము నెరవేరెను.", "1. మార్కు 15:28 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nఆ ప్రతుల్లో మార్కు 15:27 తరువాత కథనం నేరుగా తరువాతి వచనానికి కొనసాగుతుంది.\nయెషయా ప్రవచనం నెరవేరిందనే ప్రత్యేక వ్యాఖ్య అక్కడ ఉండదు.\nఅందువల్ల 15:28 అసలు మార్కు రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "ఈ వాక్యం యెషయా 53:12లోని ప్రవచనంతో సంబంధం కలిగి ఉంది.\nలూకా 22:37లో కూడా ఇదే ప్రవచనానికి సంబంధించిన మాట కనిపిస్తుంది.\nకొన్ని తరువాతి ప్రతులలో యేసు ఇద్దరు దొంగలతో సిలువ వేయబడిన సంఘటనకు వివరణగా ఇది చేర్చబడింది.\nదీనివల్ల ప్రవచన సంబంధిత వివరణ తరువాత చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "మార్కు 15:28ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట లేఖకుడు ఈ వచనాన్ని చేర్చాడని నిర్ధారించడం సాధ్యం కాదు.\nపాత నిబంధన ప్రవచనాన్ని యేసు సంఘటనతో అనుసంధానించేందుకు ఇది చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో ఈ ప్రవచన వివరణ కనిపించడం ప్రారంభమైంది.\nప్రతులను చేతితో కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఇది విస్తరించింది.\nక్రమంగా కొన్ని బైబిల్ సంచికల్లో మార్కు 15:28గా ప్రత్యేక వచనంగా చేరింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "16. లూకా 17:36 — తరువాత చేర్చబడిన వచనమా?", "reference": "లూకా 17:35–37", "content": ["లూకా 17:35: ఇద్దరు స్త్రీలు కలిసి విసురుచుండగా ఒకరు తీసికొనిపోబడుదురు, మరొకరు విడిచిపెట్టబడుదురు.", "లూకా 17:36: ఇద్దరు పొలములో ఉండగా ఒకడు తీసికొనిపోబడును, మరొకడు విడిచిపెట్టబడును.", "లూకా 17:37: వారు ఆయనతో — ప్రభువా, ఎక్కడ? అని అడుగగా ఆయన — శవము ఎక్కడ ఉంటుందో అక్కడ గద్దలు కూడుకొందని చెప్పెను.", "1. లూకా 17:36 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు ప్రతుల్లో కనిపించదు.\nఆ ప్రతుల్లో లూకా 17:35 తరువాత కథనం నేరుగా 17:37కు కొనసాగుతుంది.\nపొలములో ఉన్న ఇద్దరిలో ఒకడు తీసికొనిపోబడతాడనే వాక్యం అక్కడ ఉండదు.\nఅందువల్ల 17:36 అసలు లూకా రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "మత్తయి 24:40లో పొలములో ఉన్న ఇద్దరి గురించి సమానమైన వాక్యం కనిపిస్తుంది.\nకొన్ని తరువాతి పాఠ్య సంప్రదాయాలలో ఆ సమాంతర వాక్యం లూకా సువార్తలో కూడా చేరింది.\nకథనాన్ని మరింత విస్తరించేందుకు ఇది చేర్చబడి ఉండవచ్చని భావిస్తారు.\nదీనివల్ల మత్తయి ప్రభావంతో ఈ వచనం చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "లూకా 17:36ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి లేదా లేఖకుడిని ఖచ్చితంగా గుర్తించడం సాధ్యం కాదు.\nసమాంతర సువార్తలోని వాక్యాన్ని కాపీ చేసే సమయంలో చేర్చివుండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో కనిపించిన ఈ వచనం అనేక ప్రతుల ద్వారా విస్తరించింది.\nప్రతులను చేతితో కాపీ చేసే సమయంలో ఇది లూకా 17వ అధ్యాయంలో చేరింది.\nక్రమంగా కొన్ని బైబిల్ సంచికల్లో లూకా 17:36గా ప్రత్యేక వచన సంఖ్య పొందింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "17. లూకా 23:17 — తరువాత చేర్చబడిన వచనమా?", "reference": "లూకా 23:16–19", "content": ["లూకా 23:16: కాబట్టి ఆయనను శిక్షించి విడిచిపెట్టుదును.", "లూకా 23:17: పండుగ సందర్భమున వారికి ఒకనిని విడిచిపెట్టుట అతనికి అవసరమైయుండెను.", "లూకా 23:18: అయితే వారందరు ఒకేసారి కేకలు వేయుచు — ఇతనిని తీసివేసి బరబ్బాను మాకు విడిచిపెట్టుమని చెప్పిరి.", "లూకా 23:19: అతడు పట్టణములో జరిగిన తిరుగుబాటు మరియు నరహత్య కారణంగా చెరసాలలో వేయబడినవాడు.", "1. లూకా 23:17 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nఆ ప్రతుల్లో లూకా 23:16 తరువాత కథనం నేరుగా 23:18కు కొనసాగుతుంది.\nపండుగ సందర్భంగా ఒక ఖైదీని విడుదల చేయాలనే వివరణ అక్కడ ఉండదు.\nఅందువల్ల 23:17 అసలు లూకా రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "మత్తయి మరియు మార్కు సువార్తలలో పండుగ సమయంలో ఖైదీ విడుదల సంప్రదాయం వివరించబడింది.\nకొన్ని తరువాతి పాఠ్య సంప్రదాయాలలో ఆ వివరణను లూకా కథనంలో కూడా చేర్చారు.\nబరబ్బాను ఎందుకు విడుదల చేయాలని ప్రజలు అడిగారో వివరించేందుకు ఇది చేరి ఉండవచ్చు.\nదీనివల్ల సమాంతర సువార్తల ప్రభావంతో ఈ వచనం చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "లూకా 23:17ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట లేఖకుడు ఈ వచనాన్ని చేర్చాడని ఖచ్చితంగా నిర్ధారించబడలేదు.\nఇతర సువార్తలలోని సమాంతర వివరాలను ఆధారంగా చేసుకుని ఇది చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో కనిపించిన ఈ వివరణ క్రమంగా విస్తరించింది.\nప్రతులను చేతితో కాపీ చేసే సమయంలో ఇది లూకా 23వ అధ్యాయంలో చేరింది.\nతరువాత కొన్ని బైబిల్ సంచికల్లో లూకా 23:17గా ప్రత్యేక వచన సంఖ్య పొందింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "18. అపొస్తల కార్యములు 15:34 — తరువాత చేర్చబడిన వచనమా?", "reference": "అపొస్తల కార్యములు 15:33–35", "content": ["అపొస్తల కార్యములు 15:33: వారు కొంతకాలము అక్కడ ఉన్న తరువాత సహోదరులచేత శాంతితో అపొస్తలులయొద్దకు పంపబడిరి.", "అపొస్తల కార్యములు 15:34: సీల అక్కడనే ఉండుటకు ఇష్టపడెను.", "అపొస్తల కార్యములు 15:35: పౌలు మరియు బర్నబా అంతియొకయలో ఉండి అనేకులతో కలిసి ప్రభువు వాక్యమును బోధించుచు ప్రకటించుచుండిరి.", "1. అపొస్తల కార్యములు 15:34 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు ప్రతుల్లో కనిపించదు.\nఆ ప్రతుల్లో 15:33 తరువాత కథనం నేరుగా 15:35కు కొనసాగుతుంది.\nసీల అక్కడే ఉండిపోయాడనే వివరణ ఆ ప్రారంభ ప్రతుల్లో ఉండదు.\nఅందువల్ల 15:34 అసలు అపొస్తల కార్యముల రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "15:40లో సీల పౌలుతో కలిసి ప్రయాణించినట్లు కథనం చెబుతుంది.\nదీనికి ముందు సీల ఎక్కడ ఉన్నాడనే ప్రశ్నకు వివరణ ఇవ్వడానికి ఈ వచనం చేరి ఉండవచ్చని భావిస్తారు.\nకథనం మధ్య ఉన్న సంఘటనలను అనుసంధానించేందుకు ఇది చేర్చబడిన అవకాశం ఉంది.\nదీనివల్ల వివరణాత్మక పాఠ్యంగా ఇది తరువాత చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "అపొస్తల కార్యములు 15:34ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి లేదా లేఖకుడిని ఖచ్చితంగా గుర్తించడం సాధ్యం కాదు.\nకథనాన్ని స్పష్టంగా చేయడానికి ప్రతులను కాపీ చేసే సమయంలో ఇది చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో కనిపించిన ఈ వివరణ అనేక ప్రతుల ద్వారా విస్తరించింది.\nప్రతులను చేతితో కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఇది ప్రధాన పాఠ్యంలో చేరింది.\nక్రమంగా కొన్ని బైబిల్ సంచికల్లో అపొస్తల కార్యములు 15:34గా స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "19. అపొస్తల కార్యములు 24:7 — తరువాత చేర్చబడిన వచనమా?", "reference": "అపొస్తల కార్యములు 24:6–8", "content": ["అపొస్తల కార్యములు 24:6: అతడు దేవాలయమును అపవిత్రపరచుటకు ప్రయత్నించెను; అందుచేత మేము అతనిని పట్టుకొంటిమి.", "అపొస్తల కార్యములు 24:7: అయితే సహస్రాధిపతి లూసియ అతనిని మా చేతులనుండి బలవంతముగా తీసికొనిపోయెను.", "అపొస్తల కార్యములు 24:8: అతనిని గూర్చి ఫిర్యాదు చేసిన మమ్మల్ని నీయొద్దకు రావలెనని ఆజ్ఞాపించెను; నీవే అతనిని విచారించినయెడల మేము అతనిమీద మోపిన సంగతులన్నియు తెలిసికొందువు.", "1. అపొస్తల కార్యములు 24:7 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nఆ ప్రతుల్లో 24:6 తరువాత కథనం నేరుగా 24:8కు కొనసాగుతుంది.\nసహస్రాధిపతి లూసియ పౌలును తీసుకుపోయాడనే వివరణ అక్కడ ఉండదు.\nఅందువల్ల 24:7 అసలు అపొస్తల కార్యముల రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "అపొస్తల కార్యములు ఇతర అధ్యాయాలలో లూసియ పౌలును రక్షించిన సంఘటనలు వివరించబడాయి.\nఆ నేపథ్యాన్ని ఇక్కడ కూడా స్పష్టంగా తెలియజేయడానికి ఈ మాట చేరి ఉండవచ్చని భావిస్తారు.\nకొన్ని తరువాతి ప్రతుల్లో 24:6 చివరి భాగం మరియు 24:8 ప్రారంభ భాగం కూడా విస్తరించబడింది.\nదీనివల్ల వివరణాత్మక పాఠ్యం తరువాత చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "అపొస్తల కార్యములు 24:7ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి దీనిని చేర్చాడని ఖచ్చితంగా నిర్ధారించడం సాధ్యం కాదు.\nకథన నేపథ్యాన్ని స్పష్టంగా చేయడానికి కాపీ ప్రక్రియలో ఇది చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో ఈ విస్తృత వివరణ కనిపించింది.\nప్రతులను చేతితో కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఇది కొన్ని ప్రతుల్లో విస్తరించింది.\nక్రమంగా కొన్ని బైబిల్ సంచికల్లో అపొస్తల కార్యములు 24:7గా చేరింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "20. అపొస్తల కార్యములు 28:29 — తరువాత చేర్చబడిన వచనమా?", "reference": "అపొస్తల కార్యములు 28:28–29", "content": ["అపొస్తల కార్యములు 28:28: కాబట్టి దేవుని ఈ రక్షణ అన్యజనులకు పంపబడెనని మీకు తెలియునుగాక; వారు వినుదురు.", "అపొస్తల కార్యములు 28:29: ఆయన ఈ మాటలు చెప్పిన తరువాత యూదులు తమలో తాము బహు వాదించుకొనుచు వెళ్లిపోయిరి.", "1. అపొస్తల కార్యములు 28:29 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు ప్రతుల్లో కనిపించదు.\nఆ ప్రతుల్లో 28:28 తరువాత కథనం నేరుగా తదుపరి భాగానికి కొనసాగుతుంది.\nయూదులు తమలో తాము వాదించుకుంటూ వెళ్లిపోయారనే వాక్యం అక్కడ ఉండదు.\nఅందువల్ల 28:29 అసలు అపొస్తల కార్యముల రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "పౌలు మాటలకు యూదుల మధ్య విభేదాలు ఏర్పడినట్లు ఇతర సందర్భాల్లో కూడా కనిపిస్తుంది.\nఈ సంఘటనకు ముగింపు ఇవ్వడానికి ఇలాంటి వాక్యం చేరి ఉండవచ్చని భావిస్తారు.\nకథనాన్ని పూర్తి చేయడానికి తరువాతి లేఖకులు వివరణాత్మక మాట చేర్చివుండవచ్చు.\nదీనివల్ల ఇది తరువాతి పాఠ్య విస్తరణా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "అపొస్తల కార్యములు 28:29ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి లేదా లేఖకుడిని ఖచ్చితంగా గుర్తించడం సాధ్యం కాదు.\nకథనానికి సహజమైన ముగింపు ఇవ్వడానికి ఇది చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో కనిపించిన ఈ వచనం అనేక ప్రతుల ద్వారా విస్తరించింది.\nప్రతులను చేతితో కాపీ చేసే సమయంలో ఇది అపొస్తల కార్యముల చివరి అధ్యాయంలో చేరింది.\nక్రమంగా కొన్ని బైబిల్ సంచికల్లో అపొస్తల కార్యములు 28:29గా స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా ప్రధాన పాఠ్యంలో చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "21. రోమీయులకు 16:24 — తరువాత చేర్చబడిన వచనమా?", "reference": "రోమీయులకు 16:23–24", "content": ["రోమీయులకు 16:23: నాకు మరియు సంఘమంతటికిని అతిథియైన గాయియు మీకు వందనములు చెప్పుచున్నాడు. పట్టణ ఖజాంచియైన ఎరస్తును సహోదరుడైన క్వార్తును మీకు వందనములు చెప్పుచున్నారు.", "రోమీయులకు 16:24: మన ప్రభువైన యేసుక్రీస్తు కృప మీ అందరితో ఉండును గాక. ఆమేన్.", "1. రోమీయులకు 16:24 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు ప్రతుల్లో కనిపించదు.\nఆ ప్రతుల్లో 16:23 తరువాత పత్రిక ముగింపు ఇతర వచనాలకు కొనసాగుతుంది.\n“ప్రభువైన యేసుక్రీస్తు కృప మీ అందరితో ఉండును గాక” అనే మాట ప్రత్యేక 24వ వచనంగా ఉండదు.\nఅందువల్ల 16:24 అసలు రోమీయులకు పత్రికలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "ఇలాంటి ఆశీర్వాద వాక్యం రోమీయులకు 16:20లో కూడా కనిపిస్తుంది.\nకొన్ని తరువాతి ప్రతులలో అదే తరహా ముగింపు వాక్యం మళ్లీ చేర్చబడింది.\nపత్రికకు సంప్రదాయ ముగింపు ఇవ్వడానికి ఇది పునరావృతమై ఉండవచ్చని భావిస్తారు.\nదీనివల్ల ఇది తరువాతి పాఠ్య విస్తరణా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "రోమీయులకు 16:24ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి ఈ వచనాన్ని చేర్చాడని ఖచ్చితంగా చెప్పడం సాధ్యం కాదు.\nప్రతులను చేతితో కాపీ చేసే సమయంలో సాధారణ ఆశీర్వాద వాక్యం చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో ఈ ఆశీర్వాద వాక్యం కనిపించడం ప్రారంభమైంది.\nప్రతులను కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఇది కొన్ని ప్రతుల్లో విస్తరించింది.\nక్రమంగా కొన్ని బైబిల్ సంచికల్లో రోమీయులకు 16:24గా ప్రత్యేక వచనంగా స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వచనం తరువాత ఎలా ప్రధాన పాఠ్యంలో చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "22. 1 యోహాను 5:7–8 — తరువాత విస్తరించబడిన వచనమా?", "reference": "1 యోహాను 5:7–8", "content": ["1 యోహాను 5:7: పరలోకమందు సాక్ష్యమిచ్చువారు ముగ్గురు — తండ్రి, వాక్యము, పరిశుద్ధాత్మ; ఈ ముగ్గురు ఏకమై యున్నారు.", "1 యోహాను 5:8: భూమిమీద సాక్ష్యమిచ్చువారు ముగ్గురు — ఆత్మ, నీరు, రక్తము; ఈ ముగ్గురు ఏకమై యున్నారు.", "1. “తండ్రి, వాక్యము, పరిశుద్ధాత్మ” అనే భాగం ఎప్పటి వరకు కనిపించలేదు?", "ఈ విస్తృత వాక్యం అత్యంత పురాతన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nప్రారంభ గ్రీకు ప్రతుల్లో ప్రధానంగా ఆత్మ, నీరు మరియు రక్తము అనే మూడు సాక్ష్యాల గురించే ఉంటుంది.\n“పరలోకమందు సాక్ష్యమిచ్చువారు — తండ్రి, వాక్యము, పరిశుద్ధాత్మ” అనే భాగం తరువాతి పాఠ్య సంప్రదాయంలో కనిపిస్తుంది.\nఅందువల్ల ఈ అదనపు భాగం అసలు 1 యోహాను రచనలో ఉందా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ అదనపు భాగం ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "ఈ భాగం గ్రీకు పాఠ్య సంప్రదాయంలో చాలా ఆలస్యంగా కనిపించింది.\nముందుగా కొన్ని లాటిన్ పాఠ్య సంప్రదాయాలలో విస్తృత రూపం అభివృద్ధి చెందినట్లు కనిపిస్తుంది.\nతరువాతి కాలంలో ఈ మాట గ్రీకు ప్రతులలో కూడా చేరింది.\nదీనివల్ల అసలు పాఠ్యానికి తరువాత వివరణాత్మక విస్తరణ చేర్చబడిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ భాగాన్ని ఎవరు చేర్చారు?", "ఈ అదనపు వాక్యాన్ని మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి లేదా లేఖకుడిని ఖచ్చితంగా గుర్తించడం సాధ్యం కాదు.\nత్రిత్వ భావనకు సంబంధించిన వివరణాత్మక వ్యాఖ్య క్రమంగా పాఠ్యంలోకి ప్రవేశించి ఉండవచ్చని పాఠ్య చరిత్ర సూచిస్తుంది.\nఅందువల్ల దీనిని అసలు ఎవరు చేర్చారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ భాగం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "లాటిన్ పాఠ్య సంప్రదాయం ద్వారా ఈ విస్తృత రూపం క్రమంగా ప్రసిద్ధి చెందింది.\nతరువాత కొన్ని గ్రీకు ప్రతులు మరియు ముద్రిత బైబిల్ సంచికల్లో కూడా చేరింది.\nదీనివల్ల కొన్ని సంప్రదాయ బైబిళ్లలో 1 యోహాను 5:7–8 విస్తృత రూపంలో స్థిరపడింది.\nఅందువల్ల ప్రారంభ గ్రీకు ప్రతుల్లో లేని భాగం తరువాత ఎలా ప్రధాన పాఠ్యంలో చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "23. యోహాను 5:4 — తరువాత చేర్చబడిన వచనమా?", "reference": "యోహాను 5:3–5", "content": ["యోహాను 5:3: వాటిలో గ్రుడ్డివారు, కుంటివారు, ఎండిపోయిన అవయవములు గలవారు అనేకులు పడుకొని ఉండిరి.", "యోహాను 5:4: ఒక దూత కాలకాలమున కొలనులో దిగివచ్చి నీటిని కదిలించుచుండెను; నీరు కదిలిన తరువాత మొదట దిగినవాడు తనకున్న ఏ వ్యాధియైనను స్వస్థత పొందుచుండెను.", "యోహాను 5:5: అక్కడ ముప్పది ఎనిమిది సంవత్సరములుగా వ్యాధిగల ఒక మనుష్యుడు ఉండెను.", "1. యోహాను 5:4 ఎప్పటి వరకు కనిపించలేదు?", "ఈ వచనం కొన్ని పురాతన మరియు ముఖ్యమైన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nకొన్ని ప్రారంభ ప్రతుల్లో యోహాను 5:3 తరువాత కథనం నేరుగా 5:5కు కొనసాగుతుంది.\nదూత నీటిని కదిలించడం మరియు మొదట దిగినవాడు స్వస్థత పొందడం అనే వివరణ అక్కడ ఉండదు.\nఅందువల్ల 5:4 అసలు యోహాను రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ వచనం ఎందుకు తరువాతి ప్రతుల్లో కనిపించింది?", "యోహాను 5వ అధ్యాయంలోని రోగులు నీరు కదలడాన్ని ఎందుకు ఎదురుచూస్తున్నారో వివరించడానికి ఈ వచనం ఉపయోగపడుతుంది.\nకథనంలోని నేపథ్యాన్ని స్పష్టంగా చేయడానికి ఒక వివరణాత్మక వ్యాఖ్య చేరి ఉండవచ్చని భావిస్తారు.\nతరువాతి ప్రతుల్లో ఈ వివరణ ప్రధాన పాఠ్యంలో భాగంగా కనిపించడం ప్రారంభమైంది.\nదీనివల్ల కథన వివరణ తరువాత చేర్చబడిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ వచనాన్ని ఎవరు చేర్చారు?", "యోహాను 5:4ను మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి లేదా లేఖకుడిని ఖచ్చితంగా గుర్తించడం సాధ్యం కాదు.\nకొలనులో జరిగే విషయాన్ని వివరించే అంచు వ్యాఖ్య తరువాత పాఠ్యంలో చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ వచనాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ వచనం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి పాఠ్య సంప్రదాయాలలో ఈ వివరణాత్మక వచనం కనిపించడం ప్రారంభమైంది.\nప్రతులను చేతితో కాపీ చేసే సమయంలో ఇది యోహాను 5వ అధ్యాయంలో విస్తరించింది.\nక్రమంగా కొన్ని బైబిల్ సంచికల్లో యోహాను 5:4గా ప్రత్యేక వచన సంఖ్యతో స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని వివరణ తరువాత ఎలా ప్రధాన పాఠ్యంలో చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "24. యోహాను 7:53–8:11 — వేరే చోట్ల కనిపించిన కథనా?", "reference": "యోహాను 7:53–8:11", "content": ["యోహాను 7:53: వారందరు తమ తమ ఇండ్లకు వెళ్లిరి.", "యోహాను 8:1: యేసు ఒలీవల కొండకు వెళ్లెను.", "యోహాను 8:2: తెల్లవారగానే ఆయన మరల దేవాలయములోనికి వచ్చెను; ప్రజలందరు ఆయనయొద్దకు వచ్చిరి; ఆయన కూర్చుండి వారికి బోధించుచుండెను.", "యోహాను 8:3: అప్పుడు శాస్త్రులు మరియు పరిసయ్యులు వ్యభిచారములో పట్టబడిన ఒక స్త్రీని తీసికొని వచ్చి మధ్యలో నిలువబెట్టిరి.", "యోహాను 8:4: వారు ఆయనతో — బోధకుడా, ఈ స్త్రీ వ్యభిచారము చేయుచుండగా పట్టబడెనని చెప్పిరి.", "యోహాను 8:5: మోషే ధర్మశాస్త్రములో ఇట్టివారిని రాళ్లతో కొట్టవలెనని మాకు ఆజ్ఞాపించెను; మరి నీవేమి చెప్పుచున్నావని అడిగిరి.", "యోహాను 8:6: వారు ఆయనను శోధించుటకై ఆయనమీద నేరము మోపుటకు ఈ మాట చెప్పిరి. యేసు వంగి తన వ్రేలితో నేలమీద వ్రాయుచుండెను.", "యోహాను 8:7: వారు ఆయనను అడుగుచుండగా ఆయన నిటారుగా నిలిచి — మీలో పాపము లేనివాడు మొదట ఆమెపై రాయి వేయునుగాక అని చెప్పెను.", "యోహాను 8:8: ఆయన మరల వంగి నేలమీద వ్రాయుచుండెను.", "యోహాను 8:9: వారు అది విని పెద్దవారి మొదలుకొని ఒక్కొక్కరుగా వెళ్లిపోయిరి; యేసు ఒంటరిగా నిలిచెను మరియు ఆ స్త్రీ మధ్యలో నిలిచి ఉండెను.", "యోహాను 8:10: యేసు నిటారుగా నిలిచి — స్త్రీ, నిన్ను నిందించినవారు ఎక్కడ? ఎవడును నీకు తీర్పు తీర్చలేదా? అని అడిగెను.", "యోహాను 8:11: ఆమె — ఎవడును లేదు ప్రభువా అని చెప్పెను. యేసు — నేనును నీకు తీర్పు తీర్చను; వెళ్లి ఇకపై పాపము చేయకుమని చెప్పెను.", "1. ఈ కథ అన్ని ప్రతుల్లో ఒకే చోట ఉందా?", "ఈ కథ అన్ని పురాతన ప్రతుల్లో యోహాను 7:53–8:11 వద్ద కనిపించదు.\nకొన్ని తరువాతి ప్రతుల్లో ఈ కథ వేరే ప్రదేశాలలో కూడా కనిపిస్తుంది.\nకొన్ని పాఠ్య సంప్రదాయాలు దీనిని లూకా సువార్తకు సంబంధించిన ప్రాంతంలో ఉంచాయి.\nదీనివల్ల ఈ కథ అసలు స్థానం ఏమిటనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ కథ ఎప్పటి వరకు ఒక స్థిరమైన స్థానంలో కనిపించలేదు?", "ప్రారంభ కాలపు ముఖ్యమైన గ్రీకు ప్రతుల్లో ఈ కథ పూర్తిగా కనిపించదు.\nతరువాతి కాలంలో కథ వివిధ పాఠ్య సంప్రదాయాలలో వేర్వేరు ప్రదేశాల్లో కనిపించడం ప్రారంభమైంది.\nఒకే స్థిరమైన స్థానం లేకపోవడం ఈ కథ పాఠ్య చరిత్రపై ప్రశ్నలను కలిగిస్తుంది.\nఅందువల్ల ఇది తరువాత క్రమంగా ఒక స్థానం పొందిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ కథను యోహాను సువార్తలో ఎవరు స్థిరపరిచారు?", "ఈ కథను ప్రస్తుత యోహాను 7:53–8:11 స్థానంలో మొదట ఎవరు ఉంచారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట లేఖకుడు దీనిని అక్కడ చేర్చాడని నిర్ధారించడం సాధ్యం కాదు.\nప్రతుల కాపీ ప్రక్రియలో వివిధ పాఠ్య సంప్రదాయాల ద్వారా ఇది ప్రయాణించి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ప్రస్తుత స్థానంలో దీనిని ఎవరు స్థిరపరిచారనే విషయం స్పష్టంగా తెలియదు.", "4. ఈ కథ తరువాత ప్రస్తుత స్థానంలో ఎలా స్థిరపడింది?", "వివిధ పాఠ్య సంప్రదాయాలలో తిరిగిన తరువాత ఈ కథ అనేక తరువాతి యోహాను ప్రతుల్లో కనిపించింది.\nక్రమంగా యోహాను 7:53–8:11 స్థానం అనేక బైబిల్ సంచికల్లో సాధారణ స్థానంగా మారింది.\nప్రతులను కాపీ చేస్తూ తరతరాలకు పంపే సమయంలో ఈ స్థానం విస్తృతంగా అంగీకరించబడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని కథ తరువాత ప్రస్తుత స్థానంలో ఎలా స్థిరపడిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "25. మత్తయి 6:13 చివరి భాగం — తరువాత చేర్చబడిందా?", "reference": "మత్తయి 6:13", "content": ["మత్తయి 6:13: మమ్మును శోధనలోనికి తేకుము; దుష్టునినుండి మమ్మును విడిపించుము. రాజ్యమును, శక్తియు, మహిమయు యుగయుగములకు నీవై యున్నవి. ఆమేన్.", "1. “రాజ్యమును, శక్తియు, మహిమయు” అనే భాగం ఎప్పటి వరకు కనిపించలేదు?", "మత్తయి 6:13లోని చివరి భాగం కొన్ని పురాతన గ్రీకు మాన్యుస్క్రిప్టుల్లో కనిపించదు.\nప్రారంభ ప్రతుల్లో ప్రార్థన “దుష్టునినుండి మమ్మును విడిపించుము” అనే మాటతో ముగుస్తుంది.\n“రాజ్యమును, శక్తియు, మహిమయు యుగయుగములకు నీవై యున్నవి” అనే భాగం తరువాతి ప్రతుల్లో కనిపిస్తుంది.\nఅందువల్ల ఈ ముగింపు అసలు మత్తయి రచనలో భాగమా అనే ప్రశ్న ఏర్పడుతుంది.", "2. ఈ అదనపు భాగం ఎప్పుడు కనిపించడం ప్రారంభమైంది?", "తరువాతి పాఠ్య సంప్రదాయాలలో ఈ ప్రార్థనా ముగింపు కనిపించడం ప్రారంభమైంది.\nఆరాధన మరియు ప్రార్థనా వినియోగంలో ఉండే మహిమార్పణ వాక్య రూపంతో దీనికి సంబంధం ఉండవచ్చని భావిస్తారు.\nక్రమంగా ఇది మత్తయి 6:13కు జోడించబడిన రూపంలో అనేక ప్రతుల్లో కనిపించింది.\nదీనివల్ల ప్రార్థనా సంప్రదాయం ద్వారా ఈ భాగం చేరిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ భాగాన్ని ఎవరు చేర్చారు?", "ఈ అదనపు ప్రార్థనా ముగింపును మొదట ఎవరు చేర్చారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట వ్యక్తి దీనిని చేర్చాడని ఖచ్చితంగా చెప్పడం సాధ్యం కాదు.\nఆరాధనా పద్ధతుల్లో ఉపయోగించిన మహిమార్పణ వాక్యం క్రమంగా పాఠ్యంలో చేరి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ భాగాన్ని అసలు ఎవరు చేర్చారనే విషయం తెలియదు.", "4. ఈ భాగం తరువాత బైబిల్‌లో ఎలా స్థిరపడింది?", "తరువాతి గ్రీకు పాఠ్య సంప్రదాయాలలో ఈ ముగింపు విస్తృతంగా కనిపించింది.\nప్రతులను చేతితో కాపీ చేసే సమయంలో ఇది మత్తయి 6:13లో భాగంగా విస్తరించింది.\nక్రమంగా కొన్ని సంప్రదాయ బైబిల్ సంచికల్లో ప్రార్థనలో భాగంగా స్థిరపడింది.\nఅందువల్ల ప్రారంభ ప్రతుల్లో లేని ముగింపు తరువాత ఎలా ప్రధాన పాఠ్యంలో చేరిందనే ప్రశ్న ఏర్పడుతుంది."]}, {"title": "26. ప్రకటన గ్రంథము 22:19 — “Book of Life” లేదా “Tree of Life” మార్పా?", "reference": "ప్రకటన గ్రంథము 22:18–19", "content": ["ప్రకటన గ్రంథము 22:18: ఈ గ్రంథమందలి ప్రవచన వాక్యములను వినువారందరికి నేను సాక్ష్యమిచ్చుచున్నాను; ఎవడైనను వీటికి ఏదైనను చేర్చినయెడల ఈ గ్రంథములో వ్రాయబడిన తెగుళ్లను దేవుడు వానికి కలుగజేయును.", "ప్రకటన గ్రంథము 22:19: ఎవడైనను ఈ ప్రవచన గ్రంథ వాక్యములలో నుండి ఏదైనను తీసివేసినయెడల దేవుడు ఈ గ్రంథములో వ్రాయబడిన జీవవృక్షములోను పరిశుద్ధ పట్టణములోను వానికి కలుగు భాగమును తీసివేయును.", "1. ప్రకటన 22:19లో పాఠ్య భేదం ఏమిటి?", "కొన్ని పాఠ్య సంప్రదాయాలలో “జీవవృక్షము” అనే పదం కనిపిస్తుంది.\nఅయితే కొన్ని తరువాతి బైబిల్ సంప్రదాయాలలో “జీవగ్రంథము” అనే పద రూపం కనిపిస్తుంది.\nఒకే వచనంలో రెండు వేర్వేరు పదాలు ఉండటం ముఖ్యమైన పాఠ్య భేదంగా మారింది.\nఅందువల్ల అసలు పదం ఏది అనే ప్రశ్న ఏర్పడుతుంది.", "2. “జీవగ్రంథము” అనే పాఠ్యం ఎప్పుడు కనిపించింది?", "ప్రారంభ గ్రీకు పాఠ్య సంప్రదాయంలో “జీవవృక్షము” అనే పాఠ్యం బలంగా కనిపిస్తుంది.\nతరువాతి కొన్ని సంప్రదాయాలు “జీవగ్రంథము” అనే రూపాన్ని ఉపయోగించాయి.\nపదాల మధ్య ఉన్న సారూప్యత మరియు అనువాద సంప్రదాయాలు ఈ మార్పుకు కారణమై ఉండవచ్చని పరిశీలించబడుతుంది.\nదీనివల్ల తరువాతి పాఠ్య సంప్రదాయంలో పద మార్పు జరిగిందా అనే ప్రశ్న వస్తుంది.", "3. ఈ పద మార్పును ఎవరు చేశారు?", "ఈ పాఠ్య మార్పును మొదట ఎవరు చేశారో స్పష్టమైన చారిత్రక ఆధారం లేదు.\nఒక నిర్దిష్ట లేఖకుడు “జీవవృక్షము”ను “జీవగ్రంథము”గా మార్చాడని నిర్ధారించడం సాధ్యం కాదు.\nప్రతుల కాపీ మరియు అనువాద ప్రక్రియలలో పాఠ్య భేదం ఏర్పడి ఉండవచ్చని భావిస్తారు.\nఅందువల్ల ఈ మార్పును అసలు ఎవరు చేశారనే విషయం తెలియదు.", "4. పాఠ్య భేదం ఉన్నప్పటికీ ఏది అసలు పాఠ్యం?", "పురాతన గ్రీకు మాన్యుస్క్రిప్టుల ఆధారంగా “జీవవృక్షము” అనే పాఠ్యానికి బలమైన ఆధారం ఉందని పాఠ్య పరిశోధనలో పరిశీలించబడుతుంది.\nఅయితే కొన్ని సంప్రదాయ బైబిల్ సంచికల్లో “జీవగ్రంథము” అనే పాఠ్యం కొనసాగింది.\nదీనివల్ల ఒకే వచనానికి వేర్వేరు బైబిల్ సంప్రదాయాలలో భిన్నమైన పద రూపాలు ఏర్పడ్డాయి.\nఅందువల్ల అసలు పదం ఏమిటనే పాఠ్య చరిత్ర ప్రశ్న కొనసాగుతుంది."]}];
const channels=[{"name": "Shiva Shakthi Shankharaavam", "url": "https://www.youtube.com/c/ShivashakthiShankhaaraavam/featured"}, {"name": "SHIVASHAKTHI", "url": "https://www.youtube.com/@SHIVASHAKTHI"}, {"name": "Kiranaasthram", "url": "https://www.youtube.com/@kiranaasthram"}, {"name": "Unbeliever_rg", "url": "https://www.youtube.com/@Unbeliever_rg"}, {"name": "Hindu Jana Shakti", "url": "https://www.youtube.com/@HinduJanaShakti"}, {"name": "LALITH_KUMARK", "url": "https://www.youtube.com/@LALITH_KUMARK"}, {"name": "Shivaji Sena", "url": "https://www.youtube.com/@ShivajiSena1"}, {"name": "Telugu Ex Christian", "url": "https://www.youtube.com/@TeluguExChristian"}, {"name": "Kaapari The Shepherd", "url": "https://www.youtube.com/@KaapariTheShepherd"}, {"name": "Sri Nighasa", "url": "https://www.youtube.com/@SriNighasa"}, {"name": "Dharma Margam", "url": "https://www.youtube.com/@dharmamargam"}, {"name": "Parvathi Hindu Dharma Rakshana", "url": "https://www.youtube.com/@ParvathiHinduDharmaRakshana"}, {"name": "Mathonmadam Pai Ramabanam", "url": "https://www.youtube.com/@MathonmadampaiRamabanam"}, {"name": "Karunakar Sugguna", "url": "https://www.youtube.com/@karunakarsugguna"}, {"name": "Bible Exposer", "url": "https://www.youtube.com/@BibleExposer"}, {"name": "Krishna Dharma Rakshana", "url": "https://www.youtube.com/@krishnadharmarakshana"}, {"name": "Radha Manohar Das 108", "url": "https://www.youtube.com/@RadhaManoharDas108"}, {"name": "Akil NTR", "url": "https://www.youtube.com/@AkilNTR"}, {"name": "Gopi Sanathana Sena", "url": "https://www.youtube.com/@gopisanathanasena"}, {"name": "Bharatavarsha 4U", "url": "https://www.youtube.com/@bharatavarsha4u"}];
