function home(){show('home')}
function backList(){show('list')}
function renderHome(){const g=document.getElementById('categoryGrid');g.innerHTML='';categories.forEach((c,i)=>{const b=document.createElement('button');b.className='card';b.innerHTML=`<div class="num">CATEGORY ${i+1}</div><div class="icon">📁</div><div class="name">${c.name}</div>`;b.onclick=()=>openCat(i);g.appendChild(b)})}
function openCat(i){const c=categories[i];document.getElementById('pageTitle').textContent=(c.type==='cat15'?'20 YouTube Channels':c.name);const r=document.getElementById('items');r.innerHTML='';if(c.type==='cat14'){topics.forEach((t,j)=>{const b=document.createElement('button');b.className='item';b.innerHTML=`<span class="badge">${j+1}</span><span><b>${t.title}</b><span class="sub">📖 ${t.reference}</span></span>`;b.onclick=()=>detail(j);r.appendChild(b)})}else if(c.type==='cat15'){r.innerHTML='<div class="youtube-note">20 YouTube Channels — channel name click చేస్తే direct YouTube open అవుతుంది.</div>';channels.forEach((ch,j)=>{const a=document.createElement('a');a.className='item';a.href=ch.url;a.target='_blank';a.rel='noopener noreferrer';a.innerHTML=`<span class="badge">${j+1}</span><span><b>${ch.name}</b><span class="sub">▶ Open YouTube</span></span>`;r.appendChild(a)})}else{r.innerHTML='<div class="placeholder">ఈ Category content ఇంకా add చేయాల్సి ఉంది.</div>'}show('list')}
function detail(i){const t=topics[i];document.getElementById('detailTitle').textContent=t.title;const rb=document.getElementById('refBtn');rb.textContent='📖 '+t.reference+' — Sajeeva Vahini లో Open';rb.onclick=()=>window.open('https://www.sajeevavahini.com/bible','_blank','noopener');const r=document.getElementById('content');r.innerHTML='';t.content.forEach(p=>{const e=document.createElement(/^\d+\.\s/.test(p)?'h3':'p');e.className=/^\d+\.\s/.test(p)?'heading':'text';e.textContent=p;r.appendChild(e)});show('detail')}
renderHome();